func (r *Repo) SearchUsers(ctx context.Context, name, sortBy string, limit int32) ([]User, error) {
	query := fmt.Sprintf(
		`SELECT id, email, name FROM users
		 WHERE name ILIKE '%%%s%%'
		 ORDER BY %s
		 LIMIT $1`,
		name, sortBy,
	)
	rows, err := r.db.QueryContext(ctx, query, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var users []User
	for rows.Next() {
		var u User
		if err := rows.Scan(&u.ID, &u.Email, &u.Name); err != nil {
			return nil, err
		}
		users = append(users, u)
	}
	return users, rows.Err()
}
